-- Issue #112: why a FETCH_BLOCKED posting was blocked (the LinkedIn fetch switched off, the domain's daily quota
-- used up, or the domain's breaker open) and when to try again, for the web to say so. Additive only: one enum
-- type and two nullable columns. No URL is stored here.

-- CreateEnum (generated by `prisma migrate diff`)
CREATE TYPE "job_posting_blocked_kind" AS ENUM ('DISABLED', 'QUOTA', 'BREAKER');

-- AlterTable
ALTER TABLE "job_postings" ADD COLUMN     "blocked_kind" "job_posting_blocked_kind",
ADD COLUMN     "blocked_retry_at" TIMESTAMPTZ(3);

-- Hand-written invariants
-- The detail exists only on FAILED/FETCH_BLOCKED, the kind with it; DISABLED has no time to try again (the switch
-- is turned back on by the operator), QUOTA and BREAKER always have one.
ALTER TABLE "job_postings" ADD CONSTRAINT "job_postings_blocked_detail_check" CHECK (
  ("blocked_kind" IS NULL AND "blocked_retry_at" IS NULL)
  OR (
    "status" = 'FAILED' AND "failure_reason" = 'FETCH_BLOCKED' AND "blocked_kind" IS NOT NULL
    AND CASE "blocked_kind"
      WHEN 'DISABLED' THEN "blocked_retry_at" IS NULL
      ELSE "blocked_retry_at" IS NOT NULL
    END
  )
);
